(async () => {
  const token = canvas.tokens.controlled[0];
  if (!token) return ui.notifications.warn("Сначала выбери токен.");
  const actor = token.actor, KEY = "flags.cyberpunk-remaster.netrunnerTrace";
  const cur = foundry.utils.getProperty(actor, KEY) ?? 0;
  const set = async (v) => { const val = Math.max(0, v); await actor.update({ [KEY]: val }); ui.notifications.info(`${actor.name} — след: ${val}`); };
  new Dialog({ title: "След в сети",
    content: `<p style="text-align:center">След <b>${actor.name}</b>: <b style="font-size:1.3em">${cur}</b></p>`,
    buttons: { plus:{label:"+1",callback:()=>set(cur+1)}, minus:{label:"−1",callback:()=>set(cur-1)}, reset:{label:"Сброс",callback:()=>set(0)}, close:{label:"Закрыть"} },
    default: "plus" }).render(true);
})();
